  int unused_b = 0;
  int low = 0;
  int high = n - 1;
  while (low <= high)
  {
    int mid = (low + high) / 2;
    if (a[mid] == x)
      return mid;
    if (a[mid] < x)
      low = mid;
    else
      high = mid - 1;
  }

  return -1;
}

