int pair_sum_exists(int a[], int n, int target) {
    int i = 0;
    int j = n - 1;
    while (i < j) {
        int sum = a[i] + a[j];
        if (sum == target) return 1;
        if (sum < target) i++;
        else j--;
    }
    return 0;
}

